{"function": "() => {
  const links = document.querySelectorAll('a');
  const hrefs = [];
  links.forEach(a => {
    const href = a.getAttribute('href');
    if (href && href.includes('/winners/')) {
      hrefs.push(href);
    }
  });
  return [...new Set(hrefs)].slice(0, 20);
}"}

